import{_ as e,o as i,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Days NYC- An Introduction to MicroCeph","description":"","frontmatter":{"title":"Ceph Days NYC- An Introduction to MicroCeph","date":"2023-05-19T00:00:00.000Z","updated":"2023-05-20T00:00:00.000Z","tags":["Ceph","MicroCeph","Cluster Management","Snap","Ubuntu"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Days_NYC_-_An_Introduction_to_MicroCeph.md","filePath":"posts/2023/Ceph_Days_NYC_-_An_Introduction_to_MicroCeph.md","lastUpdated":1780459816000}'),o={name:"posts/2023/Ceph_Days_NYC_-_An_Introduction_to_MicroCeph.md"};function r(n,a,h,s,p,c){return i(),l("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-microceph-在-ceph-集群管理中的应用" tabindex="-1">会议主题：MicroCeph 在 Ceph 集群管理中的应用 <a class="header-anchor" href="#会议主题-microceph-在-ceph-集群管理中的应用" aria-label="Permalink to &quot;会议主题：MicroCeph 在 Ceph 集群管理中的应用&quot;">​</a></h4><h4 id="主讲人-chris" tabindex="-1">主讲人：Chris <a class="header-anchor" href="#主讲人-chris" aria-label="Permalink to &quot;主讲人：Chris&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>Snap 介绍</strong>：</p><ul><li>Chris 介绍了由 Canonical 开发的微软 Snap，这是一个用于集群管理的工具。</li><li>Snap 使用 Dqlite，一个兼容 SQLite 的数据库，采用 Raft 共识算法。</li><li>管理 Daemon 允许构建任意节点的集群，用于管理各种 Ceph 守护进程（如 Monitors、Managers、OSDs、Metadata Servers 等）。</li></ul></li><li><p><strong>使用场景</strong>：</p><ul><li>支持单节点 Ceph 部署，适合在笔记本电脑上运行，权限受到严格限制。</li><li>支持小型边缘集群部署，快速、可预测，适合非 Ceph 专家的普通部署者。</li></ul></li><li><p><strong>演示环节</strong>：</p><ul><li>展示了如何通过 Snap 快速部署 Ceph 集群，包括启动集群、添加节点、配置管理 Daemon 等。</li><li>演示了如何添加 OSDs 和设置 Ceph 集群，尽管集群初始化时没有存储。</li><li>展示了如何启用和配置 Ceph 的 RGW（Red Hat Gateway），并进行了简单的 S3 操作演示。</li></ul></li><li><p><strong>后续计划</strong>：</p><ul><li>未来工作包括自动化加密、网络配置、升级管理等。</li><li>强调了用户反馈的重要性，鼓励用户尝试并提供意见。</li></ul></li><li><p><strong>技术细节</strong>：</p><ul><li>Snap 不使用 LDM，而是直接使用块设备，以便更好地进行权限限制。</li><li>讨论了从单机部署扩展到数据中心部署的可能性。</li></ul></li><li><p><strong>问题与回答</strong>：</p><ul><li>回答了关于 Snap 使用的管理 Daemon 和集群状态管理的问题。</li><li>讨论了 Snap 在不同环境下的部署和扩展性。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>继续开发和完善 Snap 的功能，特别是自动化加密和升级管理。</li><li>鼓励用户尝试并提供反馈，以便进一步改进产品。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续进行技术开发和功能完善。</li><li>收集和分析用户反馈，优化产品体验。</li><li>探索更多部署和扩展场景，提高产品的适应性和灵活性。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在感谢和掌声中结束。</li></ul>',11)])])}const d=e(o,[["render",r]]);export{u as __pageData,d as default};
